proposed_command:
$token = (Get-AzAccessToken -ResourceUrl "https://api.fabric.microsoft.com").Token | ConvertFrom-SecureString -AsPlainText
$wsId = "a3f8c2d1-9e4b-4f7a-b2c1-8d9e0a1b2c3d"
$nbId = "5c7e4b1a-2d3f-4a5b-9c8d-1e2f3a4b5c6d"

# Try delete
try {
    Invoke-RestMethod -Uri "https://api.fabric.microsoft.com/v1/workspaces/$wsId/items/$nbId" `
        -Method DELETE -Headers @{Authorization="Bearer $token"}
    Write-Host "✅ Deleted notebook $nbId"
} catch {
    Write-Host "Delete failed: $($_.ErrorDetails.Message)"
    Write-Host "Trying via /notebooks endpoint..."
    try {
        Invoke-RestMethod -Uri "https://api.fabric.microsoft.com/v1/workspaces/$wsId/notebooks/$nbId" `
            -Method DELETE -Headers @{Authorization="Bearer $token"}
        Write-Host "✅ Deleted via /notebooks"
    } catch {
        Write-Host "Also failed: $($_.ErrorDetails.Message)"
    }
}

